$t=findSlug('tours',text($_GET['tour']??'',150));if(!$t)notFound();sessionOpen();$ready=paymentReady();$customer=customer();header('Cache-Control: no-store, private');$mode=paymentConfig()['mode']??'test';ob_start();echo pageHeader('Your next adventure','A few details. A great day ahead.','Choose your date, tell us who’s coming, and review your experience before secure payment.');?><div class="container"><?php if(isset($_GET['cancelled'])):?><div class="notice">Your payment was cancelled. No paid booking was created. You can review your details and try again.</div><?php endif;?><?php if(!$ready):?><div class="notice">Online checkout is not connected yet. Please <a href="/contact">contact our team</a> to plan this experience.</div><?php elseif($mode==='test'):?><div class="notice"><strong>Test payment mode.</strong> No real payment will be collected.</div><?php endif;?></div><div class="container booking-progress" aria-label="Booking steps"><span><b>1</b> Your experience</span><span class="active"><b>2</b> Your details</span><span><b>3</b> Secure payment</span></div><div class="container booking-layout"><form id="booking-form" class="form-panel"><input type="hidden" name="tourId" value="<?=esc($t['id'])?>"><h2>Make it your day.</h2><label>Preferred tour date<input name="date" type="date" min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+18 months'))?>" required></label><div class="form-grid"><label>Adults<input name="adults" type="number" min="1" max="30" value="1" required></label><label>Children<input name="children" type="number" min="0" max="29" value="0" required></label></div><p class="muted">Children use the same listed rate unless your selected experience states otherwise. Ask us about age or height restrictions before booking.</p><?php if($t['pricingMode']!=='per_person'):?><label><?=$t['pricingMode']==='per_hour'?'Number of hours':'Number of vehicles'?><input name="units" type="number" min="1" max="20" value="1" required></label><p class="muted">Up to <?=esc($t['capacity'])?> guests per <?=$t['pricingMode']==='per_hour'?'yacht':'vehicle'?>.</p><?php else:?><input type="hidden" name="units" value="1"><?php endif;?><?php if($t['addons']):?><hr><h3>Little extras, your choice.</h3><p class="muted">Per-person extras apply to every selected guest.</p><?php foreach($t['addons'] as $a):?><div class="addon-input"><label for="addon-<?=esc($a['id'])?>"><?=esc($a['title'])?><small><?=money($a['price'])?> / <?=$a['mode']==='per_person'?'person':'unit'?></small></label><?php if($a['mode']==='per_person'):?><select id="addon-<?=esc($a['id'])?>" name="addon_<?=esc($a['id'])?>"><option value="0">No</option><option value="1">Yes</option></select><?php else:?><input id="addon-<?=esc($a['id'])?>" name="addon_<?=esc($a['id'])?>" type="number" min="0" max="20" value="0"><?php endif;?></div><?php endforeach;endif;?><button type="button" class="button button-outline full" data-add-to-cart><?=commerceIcon('cart')?> Add this experience to cart</button><p class="muted">Choose your date, guests and extras above. Add more experiences before checking out.</p><hr><h3>A little about you.</h3><div class="form-grid guest-name"><label>Full name<input name="name" autocomplete="name" required maxlength="150" value="<?=esc($customer['name']??'')?>"></label><label>Email address<input name="email" type="email" autocomplete="email" required value="<?=esc($customer['email']??'')?>" <?=$customer?'readonly':''?>></label></div><label>Phone / WhatsApp<input name="phone" type="tel" autocomplete="tel" required maxlength="50"></label><label>Hotel / pickup location <span class="muted">(if applicable)</span><input name="pickup" maxlength="300" placeholder="Your hotel name and area"></label><label>Anything we should know? <span class="muted">(optional)</span><textarea name="notes" rows="3" maxlength="1200" placeholder="Special requests or access needs"></textarea></label><?=checkoutAccountFields()?><input class="honeypot" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><label class="terms-checkbox"><input type="checkbox" name="acceptedTerms" required><span>I have reviewed the tour details and agree to the <a href="/terms" target="_blank">booking terms</a> and <a href="/privacy" target="_blank">privacy policy</a>. Payment confirms receipt of my booking; the team will confirm tour arrangements separately.</span></label><button class="button full" type="submit" <?=!$ready||price($t)<=0?'disabled':''?>>Continue to secure payment <?=icon()?></button><span class="secure-note"><?=icon('shield')?>Card details are handled securely by Stripe.</span><div class="form-message" role="status" aria-live="polite"></div></form><aside class="booking-summary"><?=photo($t)?><span class="eyebrow"><?=esc(locationName($t['location']))?></span><h2><?=esc($t['title'])?></h2><p class="muted"><?=esc($t['duration'])?></p><div class="summary-lines" id="quote-lines"></div><p class="muted">All amounts are in UAE dirhams (AED). Review the total before paying. Any special arrangements must be agreed with the team.</p><a href="<?=esc(pathFor($t))?>" class="text-link">← Back to the experience</a></aside></div><script id="booking-data" type="application/json"><?=json_encode(['id'=>$t['id'],'price'=>price($t),'pricingMode'=>$t['pricingMode'],'capacity'=>$t['capacity'],'addons'=>$t['addons'],'mode'=>$mode],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><script src="/assets/booking.js?v=20261024c" defer></script><?php renderPage('Book '.$t['title'].' | Desert Sky Tourism','Choose your travel date and guests, then pay securely for your UAE experience.',ob_get_clean(),[],true);exit;
